/* wkgfx.c — implementation of wkgfx.h over the wit-bindgen C bindings.
 *
 * The bindings (gen/wkgfx.h + gen/wkgfx.c + gen/wkgfx_component_type.o) are
 * regenerated by each consumer's build.sh:
 *
 *     wit-bindgen c --world wkgfx ../gfx-compat/wit --out-dir ../gfx-compat/gen
 *
 * State is a single global surface: wk gives a node one window, and the C
 * apps this shim exists for (doomgeneric, ...) assume exactly one.
 */
#include "wkgfx.h"

#include <assert.h>
#include <stdlib.h>
#include <string.h>

#include "gen/wkgfx.h"

/* The WKGFX_K_* values are declared in our header with literal values; lock
 * them to the generated enum so a WIT reorder can't silently skew the table. */
_Static_assert(WKGFX_K_BACKQUOTE == WASI_SURFACE_SURFACE_KEY_BACKQUOTE, "first key");
_Static_assert(WKGFX_K_ARROW_DOWN == WASI_SURFACE_SURFACE_KEY_ARROW_DOWN, "arrows");
_Static_assert(WKGFX_K_ARROW_UP == WASI_SURFACE_SURFACE_KEY_ARROW_UP, "arrows");
_Static_assert(WKGFX_K_ESCAPE == WASI_SURFACE_SURFACE_KEY_ESCAPE, "escape");
_Static_assert(WKGFX_K_F12 == WASI_SURFACE_SURFACE_KEY_F12, "function keys");
_Static_assert(WKGFX_K_KATAKANA == WASI_SURFACE_SURFACE_KEY_KATAKANA, "last key");

static struct {
    int open;
    wasi_surface_surface_own_surface_t surface;
    wasi_graphics_context_graphics_context_own_context_t ctx;
    wasi_frame_buffer_frame_buffer_own_device_t device;
    wasi_io_poll_own_pollable_t frame_pollable;
    /* Kept alive so the host knows we consume these (subscribing to scroll
     * is what routes the wheel to this surface instead of panning the
     * canvas). */
    wasi_io_poll_own_pollable_t scroll_pollable;
    /* RGBA staging buffer at the live surface size, for scaled presents. */
    uint8_t *stage;
    uint32_t stage_w, stage_h;
} G;

static wasi_surface_surface_borrow_surface_t surf(void) {
    return (wasi_surface_surface_borrow_surface_t){G.surface.__handle};
}

static wasi_graphics_context_graphics_context_borrow_context_t ctx(void) {
    return wasi_graphics_context_graphics_context_borrow_context(G.ctx);
}

int wkgfx_open(uint32_t width, uint32_t height) {
    if (G.open)
        return -1;
    wasi_surface_surface_create_desc_t desc = {
        .height = {.is_some = true, .val = height},
        .width = {.is_some = true, .val = width},
    };
    G.surface = wasi_surface_surface_constructor_surface(&desc);
    G.ctx = wasi_graphics_context_graphics_context_constructor_context();
    wasi_surface_surface_method_surface_connect_graphics_context(surf(), ctx());
    G.device = wasi_frame_buffer_frame_buffer_constructor_device();
    wasi_frame_buffer_frame_buffer_method_device_connect_graphics_context(
        (wasi_frame_buffer_frame_buffer_borrow_device_t){G.device.__handle}, ctx());
    G.frame_pollable = wasi_surface_surface_method_surface_subscribe_frame(surf());
    G.scroll_pollable = wasi_surface_surface_method_surface_subscribe_pointer_scroll(surf());
    G.open = 1;
    return 0;
}

uint32_t wkgfx_width(void) {
    return wasi_surface_surface_method_surface_width(surf());
}

uint32_t wkgfx_height(void) {
    return wasi_surface_surface_method_surface_height(surf());
}

void wkgfx_wait_frame(void) {
    wasi_io_poll_method_pollable_block(
        (wasi_io_poll_borrow_pollable_t){G.frame_pollable.__handle});
    wasi_surface_surface_frame_event_t fe;
    (void)wasi_surface_surface_method_surface_get_frame(surf(), &fe);
}

int wkgfx_wait_frame_timeout(int64_t timeout_ns) {
    wasi_io_poll_borrow_pollable_t frame = {G.frame_pollable.__handle};

    if (timeout_ns < 0) {
        wkgfx_wait_frame();
        return 1;
    }

    /* A duration pollable is one-shot: subscribe fresh each call, and drop it
     * again before returning or the handle table leaks one entry per wait. */
    wasi_io_poll_own_pollable_t deadline =
        wasi_clocks_monotonic_clock_subscribe_duration((uint64_t)timeout_ns);
    wasi_io_poll_borrow_pollable_t in[2] = {
        frame,
        {deadline.__handle},
    };
    wasi_io_poll_list_borrow_pollable_t list = {.ptr = in, .len = 2};
    wkgfx_list_u32_t ready = {0};
    wasi_io_poll_poll(&list, &ready);

    /* Index 0 is the frame. `poll` may report both as ready; the frame wins,
     * because consuming it is what unblocks the host's next present. */
    int got_frame = 0;
    for (size_t i = 0; i < ready.len; i++) {
        if (ready.ptr[i] == 0)
            got_frame = 1;
    }
    wkgfx_list_u32_free(&ready);
    wasi_io_poll_pollable_drop_own(deadline);

    if (got_frame) {
        wasi_surface_surface_frame_event_t fe;
        (void)wasi_surface_surface_method_surface_get_frame(surf(), &fe);
    }
    return got_frame;
}

int wkgfx_take_frame(void) {
    if (!G.open)
        return 0;
    /* Note what this does NOT do: it does not touch the pollable. The host's
     * frame readiness is one-shot and is consumed by the `poll` that observed
     * it (wk's SurfacePollable clears frame_ready when its future resolves),
     * so by the time we get here the wake has already been spent. What
     * `get-frame` is still needed for is the CLOSED surface: the host reports
     * that by trapping out of this very call. */
    wasi_surface_surface_frame_event_t fe;
    return wasi_surface_surface_method_surface_get_frame(surf(), &fe) ? 1 : 0;
}

uint32_t wkgfx_frame_pollable(void) {
    return G.open ? G.frame_pollable.__handle : 0;
}

/* Ensure the staging buffer matches the live surface size. */
static void stage_fit(uint32_t sw, uint32_t sh) {
    if (G.stage && G.stage_w == sw && G.stage_h == sh)
        return;
    free(G.stage);
    G.stage = malloc((size_t)sw * sh * 4);
    G.stage_w = sw;
    G.stage_h = sh;
}

void wkgfx_present(const uint8_t *rgba, uint32_t w, uint32_t h) {
    uint32_t sw = wkgfx_width();
    uint32_t sh = wkgfx_height();
    if (sw == 0 || sh == 0 || w == 0 || h == 0)
        return;

    wkgfx_list_u8_t pixels;
    if (w == sw && h == sh) {
        /* Direct blit: the import borrows the list, so the caller's buffer
         * is passed straight through without a copy. */
        pixels.ptr = (uint8_t *)rgba;
        pixels.len = (size_t)w * h * 4;
    } else {
        /* Nearest-neighbor scale into the staging buffer, preserving aspect
         * with black letterboxing. */
        stage_fit(sw, sh);
        if (!G.stage)
            return;
        /* Scale factor: the larger of the two "fits" (16.16 fixed point). */
        uint64_t fx = ((uint64_t)w << 16) / sw;
        uint64_t fy = ((uint64_t)h << 16) / sh;
        uint64_t f = fx > fy ? fx : fy; /* src pixels per dst pixel */
        /* Destination extent of the image, centered. */
        uint32_t dw = (uint32_t)(((uint64_t)w << 16) / f);
        uint32_t dh = (uint32_t)(((uint64_t)h << 16) / f);
        if (dw > sw)
            dw = sw;
        if (dh > sh)
            dh = sh;
        uint32_t x0 = (sw - dw) / 2;
        uint32_t y0 = (sh - dh) / 2;
        memset(G.stage, 0, (size_t)sw * sh * 4);
        for (uint32_t dy = 0; dy < dh; dy++) {
            uint32_t sy = (uint32_t)(((uint64_t)dy * f) >> 16);
            if (sy >= h)
                sy = h - 1;
            const uint8_t *src_row = rgba + (size_t)sy * w * 4;
            uint8_t *dst_row = G.stage + ((size_t)(y0 + dy) * sw + x0) * 4;
            for (uint32_t dx = 0; dx < dw; dx++) {
                uint32_t sx = (uint32_t)(((uint64_t)dx * f) >> 16);
                if (sx >= w)
                    sx = w - 1;
                memcpy(dst_row + (size_t)dx * 4, src_row + (size_t)sx * 4, 4);
            }
            /* Letterboxed rows keep alpha opaque where the image is; the
             * black bars stay 0,0,0,0 — the compositor treats the surface
             * as opaque RGBA either way. */
        }
        pixels.ptr = G.stage;
        pixels.len = (size_t)sw * sh * 4;
    }

    wasi_graphics_context_graphics_context_own_abstract_buffer_t ab =
        wasi_graphics_context_graphics_context_method_context_get_current_buffer(ctx());
    wasi_frame_buffer_frame_buffer_own_buffer_t buf =
        wasi_frame_buffer_frame_buffer_static_buffer_from_graphics_buffer(ab);
    wasi_frame_buffer_frame_buffer_method_buffer_set(
        (wasi_frame_buffer_frame_buffer_borrow_buffer_t){buf.__handle}, &pixels);
    wasi_frame_buffer_frame_buffer_buffer_drop_own(buf);
    wasi_graphics_context_graphics_context_method_context_present(ctx());
}

/* Decode the first UTF-8 scalar of a key event's text, 0 if none/invalid. */
static uint32_t first_scalar(const uint8_t *p, size_t len) {
    if (len == 0)
        return 0;
    if (p[0] < 0x80)
        return p[0];
    if ((p[0] & 0xe0) == 0xc0 && len >= 2)
        return ((uint32_t)(p[0] & 0x1f) << 6) | (p[1] & 0x3f);
    if ((p[0] & 0xf0) == 0xe0 && len >= 3)
        return ((uint32_t)(p[0] & 0x0f) << 12) | ((uint32_t)(p[1] & 0x3f) << 6) | (p[2] & 0x3f);
    if ((p[0] & 0xf8) == 0xf0 && len >= 4)
        return ((uint32_t)(p[0] & 0x07) << 18) | ((uint32_t)(p[1] & 0x3f) << 12) |
               ((uint32_t)(p[2] & 0x3f) << 6) | (p[3] & 0x3f);
    return 0;
}

static void fill_key(wkgfx_event *ev, wkgfx_event_type type,
                     wasi_surface_surface_key_event_t *ke) {
    ev->type = type;
    ev->key = ke->key.is_some ? (int32_t)ke->key.val : -1;
    ev->ch = ke->text.is_some ? first_scalar(ke->text.val.ptr, ke->text.val.len) : 0;
    ev->repeat = ke->repeat;
    ev->alt = ke->alt_key;
    ev->ctrl = ke->ctrl_key;
    ev->meta = ke->meta_key;
    ev->shift = ke->shift_key;
    wasi_surface_surface_key_event_free(ke);
}

static void fill_pointer(wkgfx_event *ev, wkgfx_event_type type,
                         wasi_surface_surface_pointer_event_t *pe) {
    ev->type = type;
    ev->x = pe->x;
    ev->y = pe->y;
    ev->button = pe->button.is_some ? (int32_t)pe->button.val : -1;
}

int wkgfx_poll_event(wkgfx_event *ev) {
    memset(ev, 0, sizeof(*ev));
    ev->type = WKGFX_NONE;
    ev->key = -1;
    ev->button = -1;

    /* Merge order: resize first (so the app reacts to the new size before
     * interpreting positions), then pointer (move, down, up), then key
     * (down, up), then scroll. */
    wasi_surface_surface_resize_event_t re;
    if (wasi_surface_surface_method_surface_get_resize(surf(), &re)) {
        ev->type = WKGFX_RESIZE;
        ev->width = re.width;
        ev->height = re.height;
        return 1;
    }
    wasi_surface_surface_pointer_event_t pe;
    if (wasi_surface_surface_method_surface_get_pointer_move(surf(), &pe)) {
        fill_pointer(ev, WKGFX_POINTER_MOVE, &pe);
        return 1;
    }
    if (wasi_surface_surface_method_surface_get_pointer_down(surf(), &pe)) {
        fill_pointer(ev, WKGFX_POINTER_DOWN, &pe);
        return 1;
    }
    if (wasi_surface_surface_method_surface_get_pointer_up(surf(), &pe)) {
        fill_pointer(ev, WKGFX_POINTER_UP, &pe);
        return 1;
    }
    wasi_surface_surface_key_event_t ke;
    if (wasi_surface_surface_method_surface_get_key_down(surf(), &ke)) {
        fill_key(ev, WKGFX_KEY_DOWN, &ke);
        return 1;
    }
    if (wasi_surface_surface_method_surface_get_key_up(surf(), &ke)) {
        fill_key(ev, WKGFX_KEY_UP, &ke);
        return 1;
    }
    wasi_surface_surface_scroll_event_t se;
    if (wasi_surface_surface_method_surface_get_pointer_scroll(surf(), &se)) {
        ev->type = WKGFX_SCROLL;
        ev->x = se.x;
        ev->y = se.y;
        ev->dx = se.delta_x;
        ev->dy = se.delta_y;
        return 1;
    }
    return 0;
}
